mapper.select:
select reconciliation_status as tabFlag, count(id) as count from logistics_bill_cost lbc where lbc.is_deleted = false and lbc.reconciliation_status in ('toBeConfirm','confirmed')
${permissionSql}
group by lbc.reconciliation_status

select lbc.id, lb.order_type as orderType, lb.source_type as sourceType, lbc.reconciliation_status as reconciliationStatus, lc.name as channelName, lbc.transport_no as transportNo, lbc.track_no as transportNo, lbc.logistics_bill_detail_id, lbd.transportStatus, lbc.actual_weight as actualWeight, lbc.volume_weight as volumeWeight, lbc.billing_weight as billingWeight, lbc.estimated_shipping_cost as estimatedShippingCost, lbc.billing_weight_logistics as billingWeightLogistics, lbc.actual_shipping_cost as actualShippingCost, lbc.diff_shipping_cost as diffShippingCost, lb.sales_platform as salesPlatform, lb.source_id as sourceId, lb.source_code as sourceCode, lb.outstock_code as outstockCode, lb.to_country as toCountry, lb.shop_name as customerName, lb.order_time as orderTime, lb.delivery_time as deliveryTime, lbc.remark, lbc.weight_unit as weightUnit, lbc.currency from logistics_bill_cost lbc inner join logistics_bill lb on lbc.logistics_bill_id = lb.id and lb.is_deleted = false left join ( select main_id,max(track_status) as transportStatus from logistics_bill_detail where is_deleted = false group by main_id ) lbd on lb.id = lbd.main_id left join logistics_channel lc on lbc.channel_id = lc.id and lc.is_deleted = false
lbc.is_deleted = false
and lb.order_type = #{params.orderType}
and lb.source_type = #{params.sourceType}
and lbc.remark iLIKE concat('%',#{params.remark}::text,'%')
and lbc.transport_no in
#{item}
and lbc.track_no in
#{item}
and lbc.reconciliation_status in
#{item}
AND lb.order_type not in
#{item}
and lb.shop_id in
#{item}
and lb.source_code in
#{item}
and lbc.channel_id in
#{item}
and lbd.transportStatus in
#{item}
and
lbc.diff_shipping_cost > 0
0 > lbc.diff_shipping_cost
lbc.diff_shipping_cost = 0
and lb.delivery_time >= #{params.deliveryTimeList[0]} and (#{params.deliveryTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > lb.delivery_time
and lb.order_time >= #{params.orderTimeList[0]} and (#{params.orderTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > lb.order_time
ORDER BY
${item.field} ${item.sort}
lbc.id desc

